      - name: Set up Helm
        uses: azure/setup-helm@1a275c3b69536ee54be43f2070a358922e12c8d4 # v4
        with:
          version: v4.2.0

      - name: Detect prerelease
        id: prerelease
        run: |
          version=$(helm show chart charts/monty | awk '$1 == "version:" {print $2}')
          test -n "$version"
          tag="monty-$version"
          if [[ "$GITHUB_REF_TYPE" == tag && "$GITHUB_REF_NAME" != "$tag" ]]; then
            echo "Tag $GITHUB_REF_NAME does not match chart version $version" >&2
            exit 1
