{{- if .Values.networkPolicy.enabled }}
{{- $namespaceLabels := .Values.networkPolicy.ingressController.namespaceLabels }}
{{- $podLabels := .Values.networkPolicy.ingressController.podLabels }}
{{- if not $namespaceLabels }}
{{- fail "networkPolicy.ingressController.namespaceLabels must select the data-plane namespace" }}
{{- end }}
{{- if not $podLabels }}
{{- fail "networkPolicy.ingressController.podLabels must select the data-plane pods" }}
{{- end }}
{{- range $component := list "server" "worker" }}
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: {{ include "monty.fullname" $ }}-{{ $component }}
  namespace: {{ $.Release.Namespace | quote }}
  labels:
    {{- include "monty.labels" $ | nindent 4 }}
    app.kubernetes.io/component: {{ $component }}
spec:
  podSelector:
    matchLabels:
      {{- include "monty.selectorLabels" $ | nindent 6 }}
      app.kubernetes.io/component: {{ $component }}
  policyTypes:
    - Ingress
  ingress:
    - from:
        {{- if eq $component "server" }}
        - namespaceSelector:
            matchLabels:
              {{- toYaml $namespaceLabels | nindent 14 }}
          podSelector:
            matchLabels:
              {{- toYaml $podLabels | nindent 14 }}
        {{- else }}
        - podSelector:
            matchLabels:
              {{- include "monty.selectorLabels" $ | nindent 14 }}
              app.kubernetes.io/component: server
        {{- end }}
      ports:
        - protocol: TCP
          port: 8000
{{- end }}
{{- end }}

{{- range $component := list "server" "worker" }}
{{- $config := index $.Values $component }}
{{- $prefix := printf "MONTY_%s_" (upper $component) }}
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "monty.fullname" $ }}-{{ $component }}
  labels:
    {{- include "monty.labels" $ | nindent 4 }}
    app.kubernetes.io/component: {{ $component }}
spec:
  replicas: {{ $config.replicas }}
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxUnavailable: 0
      maxSurge: 1
  selector:
    matchLabels:
      {{- include "monty.selectorLabels" $ | nindent 6 }}
      app.kubernetes.io/component: {{ $component }}
  template:
    metadata:
      labels:
        {{- include "monty.selectorLabels" $ | nindent 8 }}
        app.kubernetes.io/component: {{ $component }}
    spec:
      {{- if eq $component "server" }}
      serviceAccountName: {{ include "monty.serviceAccountName" $ | quote }}
      {{- end }}
      automountServiceAccountToken: false
      terminationGracePeriodSeconds: {{ add $.Values.drainGraceSeconds 20 }}
      {{- with $.Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      securityContext:
        runAsNonRoot: true
        runAsUser: 65532
        runAsGroup: 65532
        {{- if and (eq $component "server") $.Values.objectStore.volumes }}
        fsGroup: 65532
        fsGroupChangePolicy: OnRootMismatch
        {{- end }}
        seccompProfile:
          type: RuntimeDefault
      {{- if eq $component "server" }}
      {{- with $.Values.objectStore.volumes }}
      volumes:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- end }}
      containers:
        - name: {{ $component }}
          image: {{ printf "%s/monty-%s:%s" $.Values.image.repository $component (include "monty.imageTag" $) | quote }}
          imagePullPolicy: {{ $.Values.image.pullPolicy }}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities:
              drop: [ALL]
          ports:
            - name: http
              containerPort: 8000
          env:
            - name: {{ $prefix }}HOST
              value: '0.0.0.0'
            - name: {{ $prefix }}PORT
              value: '8000'
            - name: {{ $prefix }}DRAIN_GRACE
              value: {{ $.Values.drainGraceSeconds | quote }}
            {{- if eq $component "server" }}
            - name: MONTY_SERVER_WORKER_URL
              value: {{ printf "ws://%s-worker:8000/" (include "monty.fullname" $) | quote }}
            {{- include "monty.objectStoreEnv" $ | nindent 12 }}
            {{- end }}
            {{- range $name, $value := $config.env }}
            - name: {{ $name }}
              {{- if kindIs "map" $value }}
              {{- toYaml $value | nindent 14 }}
              {{- else }}
              value: {{ $value | quote }}
              {{- end }}
            {{- end }}
          {{- if eq $component "server" }}
          {{- with $.Values.objectStore.volumeMounts }}
          volumeMounts:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- end }}
          {{- if eq $component "server" }}
          startupProbe:
            httpGet:
              path: /health
              port: http
            periodSeconds: 5
            failureThreshold: 12
          {{- end }}
          readinessProbe:
            httpGet:
              path: /health
              port: http
            periodSeconds: 5
          livenessProbe:
            httpGet:
              path: /robots.txt
              port: http
            initialDelaySeconds: 5
            periodSeconds: 10
          resources:
            {{- toYaml $config.resources | nindent 12 }}
{{- end }}

{
  "$schema": "https://json-schema.org/draft-07/schema#",
  "type": "object",
  "additionalProperties": false,
  "required": ["image", "imagePullSecrets", "objectStore", "serviceAccount", "drainGraceSeconds", "ingress", "gateway", "extraObjects", "networkPolicy", "server", "worker"],
  "properties": {
    "image": {
      "type": "object",
      "additionalProperties": false,
      "required": ["repository", "tag", "pullPolicy"],
      "properties": {
        "repository": {"type": "string", "minLength": 1, "pattern": "^[^\\s]+[^/\\s]$"},
        "tag": {
          "description": "Shared image version override. Empty uses Chart.appVersion.",
          "type": "string",
          "pattern": "^$|^[a-zA-Z0-9_][a-zA-Z0-9_.-]{0,127}$",
          "not": {"const": "latest"}
        },
        "pullPolicy": {"type": "string", "enum": ["Always", "IfNotPresent", "Never"]}
      }
    },
    "imagePullSecrets": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["name"],
        "properties": {"name": {"type": "string", "minLength": 1}}
      }
    },
    "objectStore": {
      "type": "object",
      "additionalProperties": false,
      "required": ["env", "volumeMounts", "volumes"],
      "properties": {
        "uri": {"type": ["string", "null"]},
        "env": {
          "type": "object",
          "propertyNames": {"pattern": "^[A-Za-z_][A-Za-z0-9_]*$"},
          "additionalProperties": {"$ref": "#/definitions/envValue"}
        },
        "volumeMounts": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["name", "mountPath"],
            "properties": {
              "name": {"type": "string", "minLength": 1},
              "mountPath": {"type": "string", "pattern": "^/"},
              "readOnly": {"type": "boolean"}
            }
          }
        },
        "volumes": {
          "type": "array",
          "items": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string", "minLength": 1}}}
        }
      }
    },
    "serviceAccount": {
      "type": "object",
      "additionalProperties": false,
      "required": ["create", "name", "annotations"],
      "properties": {
        "create": {"type": "boolean"},
        "name": {"type": "string"},
        "annotations": {"$ref": "#/definitions/annotations"}
      }
    },
    "drainGraceSeconds": {"type": "integer", "minimum": 0},
    "ingress": {
      "type": "object",
      "additionalProperties": false,
      "required": ["enabled", "ingressClassName", "hostnames", "tls", "secretName", "annotations"],
      "properties": {
        "enabled": {"type": "boolean"},
        "ingressClassName": {"type": "string"},
        "hostnames": {"$ref": "#/definitions/hostnames"},
        "tls": {"type": "boolean"},
        "secretName": {"type": "string"},
        "annotations": {"$ref": "#/definitions/annotations"}
      }
    },
    "gateway": {
      "type": "object",
      "additionalProperties": false,
      "required": ["enabled", "create", "gatewayClassName", "name", "namespace", "sectionName", "hostnames", "tls", "tlsSecretName", "gatewayAnnotations", "annotations", "filters"],
      "properties": {
        "enabled": {"type": "boolean"},
        "create": {"type": "boolean"},
        "gatewayClassName": {"type": "string"},
        "name": {"type": "string"},
        "namespace": {"type": "string"},
        "sectionName": {"type": "string"},
        "hostnames": {"$ref": "#/definitions/hostnames"},
        "tls": {"type": "boolean"},
        "tlsSecretName": {"type": "string"},
        "gatewayAnnotations": {"$ref": "#/definitions/annotations"},
        "annotations": {"$ref": "#/definitions/annotations"},
        "filters": {
          "type": "array",
          "items": {"type": "object", "required": ["type"], "properties": {"type": {"type": "string", "minLength": 1}}}
        }
      }
    },
    "extraObjects": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["apiVersion", "kind", "metadata"],
        "properties": {
          "apiVersion": {"type": "string", "minLength": 1},
          "kind": {"type": "string", "minLength": 1},
          "metadata": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string", "minLength": 1}}}
        }
      }
    },
    "networkPolicy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["enabled", "ingressController"],
      "properties": {
        "enabled": {"type": "boolean"},
        "ingressController": {
          "type": "object",
          "additionalProperties": false,
          "required": ["namespaceLabels", "podLabels"],
          "properties": {
            "namespaceLabels": {"$ref": "#/definitions/labels"},
            "podLabels": {"$ref": "#/definitions/labels"}
          }
        }
      }
    },
    "server": {"$ref": "#/definitions/component"},
    "worker": {"$ref": "#/definitions/component"}
  },
  "definitions": {
    "envValue": {
      "oneOf": [
        {"type": "string"},
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["value"],
          "properties": {"value": {"type": "string"}}
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["valueFrom"],
          "properties": {"valueFrom": {"type": "object", "minProperties": 1}}
        }
      ]
    },
    "hostnames": {
      "type": "array",
      "uniqueItems": true,
      "items": {"type": "string", "maxLength": 253, "pattern": "^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$"}
    },
    "annotations": {"type": "object", "additionalProperties": {"type": "string"}},
    "labels": {
      "type": "object",
      "additionalProperties": {"type": "string", "minLength": 1}
    },
    "component": {
      "type": "object",
      "additionalProperties": false,
      "required": ["replicas", "resources", "env"],
      "properties": {
        "replicas": {"type": "integer", "minimum": 1},
        "resources": {"type": "object"},
        "env": {
          "type": "object",
          "propertyNames": {"pattern": "^[A-Za-z_][A-Za-z0-9_]*$"},
          "additionalProperties": {"$ref": "#/definitions/envValue"}
        }
      }
    }
  }
}

{{- if and .Values.gateway.enabled .Values.gateway.create }}
apiVersion: gateway.networking.k8s.io/v1
kind: Gateway
metadata:
  name: {{ include "monty.gatewayName" . }}
  labels:
    {{- include "monty.labels" . | nindent 4 }}
  {{- with .Values.gateway.gatewayAnnotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  gatewayClassName: {{ .Values.gateway.gatewayClassName | quote }}
  listeners:
    {{- range $index, $host := .Values.gateway.hostnames }}
    - name: {{ if $.Values.gateway.tls }}https{{ else }}http{{ end }}{{ if $index }}-{{ $index }}{{ end }}
      hostname: {{ $host | quote }}
      {{- if $.Values.gateway.tls }}
      protocol: HTTPS
      port: 443
      tls:
        mode: Terminate
        certificateRefs:
          - name: {{ $.Values.gateway.tlsSecretName | quote }}
      {{- else }}
      protocol: HTTP
      port: 80
      {{- end }}
      allowedRoutes:
        namespaces:
          from: Same
    {{- end }}
{{- end }}

{{- range $component := list "server" "worker" }}
---
apiVersion: v1
kind: Service
metadata:
  name: {{ include "monty.fullname" $ }}-{{ $component }}
  labels:
    {{- include "monty.labels" $ | nindent 4 }}
    app.kubernetes.io/component: {{ $component }}
spec:
  type: ClusterIP
  selector:
    {{- include "monty.selectorLabels" $ | nindent 4 }}
    app.kubernetes.io/component: {{ $component }}
  ports:
    - name: http
      port: 8000
      targetPort: http
{{- end }}

{{- if .Values.ingress.enabled }}
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: {{ include "monty.fullname" . }}-server
  labels:
    {{- include "monty.labels" . | nindent 4 }}
  {{- with .Values.ingress.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  {{- with .Values.ingress.ingressClassName }}
  ingressClassName: {{ . | quote }}
  {{- end }}
  {{- if .Values.ingress.tls }}
  tls:
    - hosts:
        {{- toYaml .Values.ingress.hostnames | nindent 8 }}
      secretName: {{ .Values.ingress.secretName | quote }}
  {{- end }}
  rules:
    {{- range .Values.ingress.hostnames }}
    - host: {{ . | quote }}
      http:
        paths:
          - path: /
            pathType: Prefix
            backend:
              service:
                name: {{ include "monty.fullname" $ }}-server
                port:
                  number: 8000
    {{- end }}
{{- end }}

{{- if .Values.gateway.enabled }}
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: {{ include "monty.fullname" . }}-server
  labels:
    {{- include "monty.labels" . | nindent 4 }}
  {{- with .Values.gateway.annotations }}
  annotations:
    {{- toYaml . | nindent 4 }}
  {{- end }}
spec:
  parentRefs:
    - name: {{ include "monty.gatewayName" . }}
      {{- if and (not .Values.gateway.create) .Values.gateway.namespace }}
      namespace: {{ .Values.gateway.namespace | quote }}
      {{- end }}
      {{- with .Values.gateway.sectionName }}
      sectionName: {{ . | quote }}
      {{- end }}
  hostnames:
    {{- toYaml .Values.gateway.hostnames | nindent 4 }}
  rules:
    - matches:
        - path:
            type: PathPrefix
            value: /
      {{- with .Values.gateway.filters }}
      filters:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      backendRefs:
        - name: {{ include "monty.fullname" . }}-server
          port: 8000
{{- end }}

{{- range .Values.extraObjects }}
---
{{ toYaml . }}
{{- end }}

{{- $storeUri := include "monty.objectStoreUri" . }}
{{- if and $storeUri (not (regexMatch "^((s3|s3a|gs|az|abfs|abfss)://[^/[:space:]]+(/[^[:space:]]*)?|file:///[^[:space:]]+|memory://)$" $storeUri)) }}
{{- fail "objectStore.uri must use s3://, gs://, az://, file:/// or memory:// (or a supported backend alias)" }}
{{- end }}
{{- if and (eq $storeUri "memory://") (gt (int .Values.server.replicas) 1) }}
{{- fail "objectStore.uri memory:// requires server.replicas=1; use a shared store for multiple servers" }}
{{- end }}
{{- if and (hasPrefix "file://" $storeUri) (not .Values.objectStore.volumeMounts) }}
{{- fail "objectStore.volumeMounts must provide a writable directory for a file:// store" }}
{{- end }}
{{- $managedEnv := list "MONTY_SERVER_HOST" "MONTY_SERVER_PORT" "MONTY_SERVER_DRAIN_GRACE" "MONTY_SERVER_WORKER_URL" "MONTY_SERVER_OBJECT_STORE_URI" "MONTY_WORKER_HOST" "MONTY_WORKER_PORT" "MONTY_WORKER_DRAIN_GRACE" }}
{{- range $source, $env := dict "server" .Values.server.env "worker" .Values.worker.env "objectStore" .Values.objectStore.env }}
{{- range $name, $_ := $env }}
{{- if eq $name "MONTY_SERVER_DUMP_KEY" }}
{{- fail "MONTY_SERVER_DUMP_KEY is no longer supported; configure objectStore instead" }}
{{- end }}
{{- if has $name $managedEnv }}
{{- fail (printf "%s.env.%s is managed by the chart" $source $name) }}
{{- end }}
{{- end }}
{{- end }}
{{- range $name, $_ := .Values.objectStore.env }}
{{- if hasKey $.Values.server.env $name }}
{{- fail (printf "%s must be set in only one of objectStore.env or server.env" $name) }}
{{- end }}
{{- end }}
{{- if and .Values.ingress.enabled .Values.gateway.enabled }}
{{- fail "enable only one of ingress.enabled or gateway.enabled" }}
{{- end }}
{{- if .Values.ingress.enabled }}
{{- if not .Values.ingress.hostnames }}
{{- fail "ingress.hostnames is required when ingress is enabled" }}
{{- end }}
{{- if and .Values.ingress.tls (not .Values.ingress.secretName) }}
{{- fail "ingress.secretName is required when ingress.tls is enabled" }}
{{- end }}
{{- end }}
{{- if .Values.gateway.enabled }}
{{- if not .Values.gateway.hostnames }}
{{- fail "gateway.hostnames is required when gateway is enabled" }}
{{- end }}
{{- if .Values.gateway.create }}
{{- if not .Values.gateway.gatewayClassName }}
{{- fail "gateway.gatewayClassName is required when gateway.create is true" }}
{{- end }}
{{- if .Values.gateway.namespace }}
{{- fail "gateway.namespace is only supported for an existing Gateway" }}
{{- end }}
{{- if and .Values.gateway.tls (not .Values.gateway.tlsSecretName) }}
{{- fail "gateway.tlsSecretName is required when creating a TLS Gateway" }}
{{- end }}
{{- if .Values.gateway.sectionName }}
